    /// </description>
    /// </item>
    /// <item>
    /// <term>params.timeInForce</term>
    /// <description>
    /// string : Must match orderType: FOK for MARKET, GTC for LIMIT
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.slippage</term>
    /// <description>
    /// string : slippage for market orders (default 5%)
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.fundingSource</term>
    /// <description>
    /// string : Funding source. Enum: MPC, CEX. Default MPC
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.fundTransferAmount</term>
    /// <description>
    /// string : Auto-transfer amount before order (wei). Must be > 0 if provided
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.accountType</term>
    /// <description>
    /// string : Payment account type. Enum: SPOT, FUNDING
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.feeRateBps</term>
    /// <description>
    /// string : Payment account type. Enum: SPOT, FUNDING
    /// </description>
    /// </item>
    /// <item>
    /// <term>params.cost</term>
    /// <description>
    /// string : Buy prediction market with USDT cost, only for buy side
    /// </description>
    /// </item>
    /// </list>
    /// </remarks>
    /// <returns> <term>object</term> a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure).</returns>
    public async Task<PredictionOrder> CreateOrder(string outcome, string type, string side, double amount, double? price2 = 0, Dictionary<string, object> parameters = null)
    {
        var price = price2 == 0 ? null : (object)price2;
        var res = await this.createOrder(outcome, type, side, amount, price, parameters);
        return new PredictionOrder(res);
    }
    /// <summary>
    /// create a market order by providing the symbol, side and cost
    /// </summary>
    /// <remarks>
    /// See <see href="https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/trade#place-order"/>  <br/>
    /// <list type="table">
    /// <item>
    /// <term>params</term>
    /// <description>
    /// object : extra parameters specific to the exchange API endpoint
    /// </description>
    /// </item>
    /// </list>
    /// </remarks>
    /// <returns> <term>object</term> an [order structure]{@link https://docs.ccxt.com/?id=order-structure}.</returns>
    public async Task<PredictionOrder> CreateMarketOrderWithCost(string symbol, string side, double cost, Dictionary<string, object> parameters = null)
    {
        var res = await this.createMarketOrderWithCost(symbol, side, cost, parameters);
        return new PredictionOrder(res);
    }
    /// <summary>
    /// cancels a single open order
    /// </summary>
    /// <remarks>
    /// See <see href="https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/trade#batch-cancel-orders"/>  <br/>
    /// <list type="table">
    /// <item>
    /// <term>outcome</term>
    /// <description>
    /// string : unified outcome
    /// </description>
    /// </item>
    /// <item>
    /// <term>params</term>
    /// <description>
    /// object : extra parameters specific to the exchange API endpoint
    /// </description>
    /// </item>
    /// </list>
    /// </remarks>
    /// <returns> <term>object</term> a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure).</returns>
    public async Task<PredictionOrder> CancelOrder(string id, string outcome = null, Dictionary<string, object> parameters = null)
    {
        var res = await this.cancelOrder(id, outcome, parameters);
        return new PredictionOrder(res);
    }
    /// <summary>
    /// cancels multiple open orders
    /// </summary>
    /// <remarks>
    /// See <see href="https://developers.binance.com/en/docs/catalog/web3-wallet-prediction-trading/api/rest-api/trade#batch-cancel-orders"/>  <br/>
    /// <list type="table">
    /// <item>
    /// <term>outcome</term>
    /// <description>
    /// string : unified outcome (required)
    /// </description>
    /// </item>
    /// <item>
    /// <term>params</term>
    /// <description>
    /// object : extra parameters specific to the exchange API endpoint
    /// </description>
    /// </item>
    /// </list>
    /// </remarks>
    /// <returns> <term>object[]</term> a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure).</returns>
    public async Task<List<PredictionOrder>> CancelOrders(List<string> ids, string outcome = null, Dictionary<string, object> parameters = null)
    {
        var res = await this.cancelOrders(ids, outcome, parameters);
        return ((IList<object>)res).Select(item => new PredictionOrder(item)).ToList<PredictionOrder>();
    }
}
